(window.V2_TALK=window.V2_TALK||{})["portraits"]={"portraits/bains":[{"id":"V_portraits_bains_01","title":"La salle de bains occupée","premise":"Tom needs the bathroom, but Dad is relaxing in a face mask.","cefr":"C2","lines":[{"speaker":"Tom","fr":"Papa, tu sors bientôt ? J'ai un besoin immédiat de la salle de bains !","en":"Dad, are you coming out soon? I need the bathroom right now!","spans":[[39,47,"fr_immediat_adj"]]},{"speaker":"Papa","fr":"Deux minutes ! Mon masque au concombre doit sécher.","en":"Two minutes! My cucumber mask has to dry.","spans":[]},{"speaker":"Tom","fr":"Ton masque vert ? Avec ton nez saillant, tu ressembles à une grenouille.","en":"Your green mask? With your pointy nose, you look like a frog.","spans":[[31,39,"fr_saillant_adj"]]},{"speaker":"Papa","fr":"Merci bien… Et toi, tu ne devais pas faire tes devoirs de français ?","en":"Thanks a lot… And weren't you supposed to do your French homework?","spans":[]},{"speaker":"Tom","fr":"Si : « Le nom est-il masculin ou féminin ? » « Bateau », c'est masculin, facile.","en":"I am: \"Is the noun masculine or feminine?\" \"Bateau\" is masculine, easy.","spans":[[21,29,"fr_masculin_adj"],[63,71,"fr_masculin_adj"]]},{"speaker":"Papa","fr":"Bravo. Et ce petit bateau dans la baignoire, tu le gardes encore ?","en":"Good job. And that little boat in the tub, are you still keeping it?","spans":[]},{"speaker":"Tom","fr":"Oui ! Il a une valeur affective : c'est Papi qui me l'a offert.","en":"Yes! It has sentimental value: Grandpa gave it to me.","spans":[[22,31,"fr_affectif_adj"]]},{"speaker":"Papa","fr":"D'accord. Mais ce savon en forme de canard est un peu inadapté à ton âge, non ?","en":"OK. But that duck-shaped soap is a bit young for you, isn't it?","spans":[[54,62,"fr_inadapte_adj"]]},{"speaker":"Tom","fr":"Bon, je vais à la salle de bains d'en bas. Je ne suis pas dépendant de la tienne !","en":"Fine, I'll use the bathroom downstairs. I don't depend on yours!","spans":[[58,67,"fr_dependant_adj"]]}]}],"portraits/classe":[{"id":"V_portraits_classe_01","title":"Après le contrôle","premise":"After a math test, Tom complains to his teacher.","cefr":"C1","lines":[{"speaker":"Tom","fr":"Madame, ce contrôle de maths était détestable !","en":"Ma'am, that math test was awful!","spans":[[35,45,"fr_detestable_adj"]]},{"speaker":"Mme Petit","fr":"Détestable ? Tu exagères, Tom. Regarde ton exercice sur les droites.","en":"Awful? You're exaggerating, Tom. Look at your exercise on lines.","spans":[[0,10,"fr_detestable_adj"]]},{"speaker":"Tom","fr":"J'ai tracé une ligne oblique au lieu d'une ligne verticale…","en":"I drew a slanted line instead of a vertical one…","spans":[[21,28,"fr_oblique_adj"]]},{"speaker":"Mme Petit","fr":"Oui, mais tu as compris que le prix est proportionnel au poids. C'est le plus important.","en":"Yes, but you understood that the price is proportional to the weight. That's what matters most.","spans":[[40,53,"fr_proportionnel_adj"]]},{"speaker":"Tom","fr":"J'étais fatigué. Je n'étais pas très lucide hier soir.","en":"I was tired. My head wasn't very clear last night.","spans":[[37,43,"fr_lucide_adj"]]},{"speaker":"Mme Petit","fr":"Alors voici un conseil indirect : regarde à quelle heure tu te couches.","en":"Then here's an indirect piece of advice: look at what time you go to bed.","spans":[[23,31,"fr_indirect_adj"]]},{"speaker":"Tom","fr":"Ce n'est pas très indirect, Madame !","en":"That's not very indirect, ma'am!","spans":[[18,26,"fr_indirect_adj"]]},{"speaker":"Mme Petit","fr":"Non, c'est vrai. Allez, va jouer, la cloche a sonné.","en":"No, that's true. Go on, go play, the bell has rung.","spans":[]}]}],"portraits/cour":[{"id":"V_portraits_cour_01","title":"Le grand mur de la cour","premise":"At recess, Léa and Inès watch a painter make a mural in the schoolyard.","cefr":"C2","lines":[{"speaker":"Léa","fr":"Inès, tu as vu le grand mur ? Le peintre dessine un garçon qui aide un vieux monsieur.","en":"Inès, did you see the big wall? The painter is drawing a boy helping an old man.","spans":[]},{"speaker":"Inès","fr":"Mme Petit dit que c'est un message humaniste : on doit s'aider les uns les autres.","en":"Mrs. Petit says it's a humanist message: we should help one another.","spans":[[35,44,"fr_humaniste_adj"]]},{"speaker":"Léa","fr":"Comme nous deux. Quand je t'aide, tu m'aides. C'est réciproque !","en":"Like the two of us. When I help you, you help me. It goes both ways!","spans":[[52,62,"fr_reciproque_adj"]]},{"speaker":"Inès","fr":"Pas comme Lucas. Il a caché le goûter de Noé et après, il s'est moqué de lui.","en":"Not like Lucas. He hid Noé's snack and then made fun of him.","spans":[]},{"speaker":"Léa","fr":"C'est méprisable ! Il n'a aucun sens moral, ce garçon.","en":"That's low! That boy has no sense of right and wrong.","spans":[[6,16,"fr_meprisable_adj"],[37,42,"fr_moral_adj"]]},{"speaker":"Mme Petit","fr":"Les filles, Lucas va s'excuser. Ne vous inquiétez pas.","en":"Girls, Lucas is going to apologize. Don't worry.","spans":[]},{"speaker":"Inès","fr":"Moi, plus tard, je veux être pilote… et aider les gens, comme sur le mur.","en":"When I grow up, I want to be a pilot… and help people, like on the wall.","spans":[]},{"speaker":"Léa","fr":"Une aspirante pilote ! Maman dit que c'est ça, le féminisme : les filles peuvent tout faire.","en":"An aspiring pilot! Mom says that's what feminism is: girls can do anything.","spans":[[4,13,"fr_aspirant_adj"],[50,59,"fr_feminisme_noun"]]},{"speaker":"Mme Petit","fr":"Exactement. Et avec la croissance démographique du village, on aura bientôt besoin d'un aéroport !","en":"Exactly. And with the village's population growth, we'll soon need an airport!","spans":[[34,47,"fr_demographique_adj"]]}]}],"portraits/sejour":[{"id":"V_portraits_sejour_01","title":"Le circuit de Tom","premise":"On a rainy afternoon in the family den, Tom will not share his toy race car.","cefr":"C2","lines":[{"speaker":"Maman","fr":"Marc, tu as vu le nouveau canapé de ta sœur ? Il n'est pas très esthétique…","en":"Marc, have you seen your sister's new couch? It's not very pretty…","spans":[[64,74,"fr_esthetique_adj"]]},{"speaker":"Papa","fr":"Non, mais il est confortable. Et avec ses triplés, elle n'a pas le temps de choisir !","en":"No, but it's comfortable. And with her triplets, she has no time to shop around!","spans":[]},{"speaker":"Maman","fr":"Trois bébés d'un coup ! Le maire dit que la natalité du village a doublé grâce à elle.","en":"Three babies at once! The mayor says the village birthrate doubled thanks to her.","spans":[[44,52,"fr_natalite_noun"]]},{"speaker":"Papa","fr":"Ha ha ! Tom, tu joues encore tout seul avec ta voiture rouge ?","en":"Ha ha! Tom, are you still playing by yourself with your red car?","spans":[]},{"speaker":"Tom","fr":"Oui, j'ai mon circuit individuel. Le bus jaune reste sur le grand circuit.","en":"Yes, I have my own track. The yellow bus stays on the big track.","spans":[[22,32,"fr_individuel_adj"]]},{"speaker":"Papa","fr":"Quel individualisme ! Tu peux partager avec ta sœur, non ?","en":"Such individualism! You can share with your sister, can't you?","spans":[[5,19,"fr_individualisme_noun"]]},{"speaker":"Tom","fr":"Léa est encline à tout casser, Papa. C'est un fait.","en":"Léa tends to break everything, Dad. That's a fact.","spans":[[8,15,"fr_enclin_adj"]]},{"speaker":"Léa","fr":"Soi-disant ! C'est toi qui as cassé le pont la semaine dernière.","en":"So you say! You're the one who broke the bridge last week.","spans":[[0,10,"fr_soi_disant_adj"]]},{"speaker":"Maman","fr":"Bon, la paix ! Qui est preneur d'un chocolat chaud ?","en":"OK, that's enough! Who's up for a hot chocolate?","spans":[[23,30,"fr_preneur_noun"]]},{"speaker":"Tom","fr":"Moi ! Mais pas dans la tasse de tante Julie, avec sa fumée violette. Quelle étrangeté, ce thé !","en":"Me! But not in Aunt Julie's cup with the purple steam. What a strange tea!","spans":[[76,85,"fr_etrangete_noun"]]}]}],"portraits/boutique":[{"id":"V_portraits_boutique_01","title":"La boule à neige","premise":"At the museum gift shop, Léa wants a snow globe of the Eiffel Tower.","cefr":"C2","lines":[{"speaker":"Léa","fr":"Maman, je peux acheter une boule à neige avec la tour Eiffel ?","en":"Mom, can I buy a snow globe with the Eiffel Tower?","spans":[]},{"speaker":"Maman","fr":"Encore ? Tu deviens dépensière, ma chérie.","en":"Another one? You're turning into a big spender, sweetie.","spans":[[20,30,"fr_depensier_adj"]]},{"speaker":"Léa","fr":"Mais c'est le monument le plus emblématique de Paris ! Et le prix est attractif : trois euros.","en":"But it's the most iconic monument in Paris! And the price is good: three euros.","spans":[[31,43,"fr_emblematique_adj"],[70,79,"fr_attractif_adj"]]},{"speaker":"Maman","fr":"Une somme modique, c'est vrai. D'accord, mais avec ton argent de poche.","en":"A small sum, that's true. OK, but with your allowance.","spans":[[10,17,"fr_modique_adj"]]},{"speaker":"Papa","fr":"Regardez cette dame : elle porte au moins dix sacs !","en":"Look at that lady: she's carrying at least ten bags!","spans":[]},{"speaker":"Maman","fr":"Chut, Marc. Nous aussi, nous sommes privilégiés : on peut voyager en vacances.","en":"Shh, Marc. We're lucky too: we can travel on vacation.","spans":[[36,47,"fr_privilegie_adj"]]},{"speaker":"Léa","fr":"Et mon sac en tissu ? Ils sont tous pareils, je vais le perdre.","en":"And my tote bag? They all look the same, I'll lose it.","spans":[]},{"speaker":"Papa","fr":"Écris ton nom dessus. Il sera facilement identifiable.","en":"Write your name on it. It'll be easy to spot.","spans":[[41,53,"fr_identifiable_adj"]]},{"speaker":"Maman","fr":"Et ton frère ? Il veut un souvenir, mais il est trop orgueilleux pour le demander.","en":"What about your brother? He wants a souvenir, but he's too proud to ask.","spans":[[53,64,"fr_orgueilleux_adj"]]}]}],"portraits/cuisine":[{"id":"V_portraits_cuisine_01","title":"Le gâteau disparu","premise":"In Grandpa's kitchen, a sleepy Tom confesses that he ate his sister's cake.","cefr":"C1","lines":[{"speaker":"M. Roux","fr":"Entrez, entrez ! La cuisine est petite, mais elle est accueillante.","en":"Come in, come in! The kitchen is small, but it's welcoming.","spans":[[54,66,"fr_accueillant_adj"]]},{"speaker":"Papi Henri","fr":"Tends ton assiette, Tom. Tu bâilles encore ? Tu t'es couché tard ?","en":"Hold out your plate, Tom. Yawning again? Did you go to bed late?","spans":[]},{"speaker":"Tom","fr":"Un peu… J'ai mangé le gâteau de Léa en cachette, cette nuit. Je suis honteux.","en":"A little… I secretly ate Léa's cake last night. I'm ashamed.","spans":[[69,76,"fr_honteux_adj"]]},{"speaker":"Papi Henri","fr":"Ce n'est pas très malin, mon grand ! Il fallait demander.","en":"That wasn't very smart, big guy! You should have asked.","spans":[[18,23,"fr_malin_adj"]]},{"speaker":"M. Roux","fr":"Allez, ce n'est pas grave. Ton grand-père est bienveillant, il ne va pas te gronder.","en":"Come on, it's no big deal. Your grandpa is kind, he won't scold you.","spans":[[46,58,"fr_bienveillant_adj"]]},{"speaker":"Tom","fr":"Demain, je refais un gâteau pour Léa. C'est judicieux, non ?","en":"Tomorrow I'll make Léa a new cake. That's a wise idea, right?","spans":[[44,53,"fr_judicieux_adj"]]},{"speaker":"Papi Henri","fr":"Très judicieux. Et elle t'aidera à le manger : le plaisir sera mutuel !","en":"Very wise. And she'll help you eat it: the pleasure will be mutual!","spans":[[5,14,"fr_judicieux_adj"],[63,69,"fr_mutuel_adj"]]}]}],"portraits/infirmerie":[{"id":"V_portraits_infirmerie_01","title":"La tension de Papi","premise":"Grandpa Henri gets a checkup in the nurse's room, with Tom as helper.","cefr":"C2","lines":[{"speaker":"L'infirmière","fr":"Bonjour, monsieur Henri. Asseyez-vous, je vais prendre votre tension artérielle.","en":"Hello, Mr. Henri. Have a seat, I'm going to take your blood pressure.","spans":[[69,79,"fr_arteriel_adj"]]},{"speaker":"Papi Henri","fr":"Encore ? Je suis en pleine forme !","en":"Again? I'm in great shape!","spans":[]},{"speaker":"L'infirmière","fr":"Juste une vérification. Tom, pose ton doigt ici : l'appareil lit ton empreinte digitale.","en":"Just a check. Tom, put your finger here: the machine reads your fingerprint.","spans":[[79,87,"fr_digital_adj"]]},{"speaker":"Tom","fr":"Ça chatouille ! Papi, ton genou te fait encore mal ?","en":"That tickles! Grandpa, does your knee still hurt?","spans":[]},{"speaker":"Papi Henri","fr":"Un peu. Mais je marche tous les jours : c'est thérapeutique, d'après le docteur.","en":"A little. But I walk every day: the doctor says it's good therapy.","spans":[[46,59,"fr_therapeutique_adj"]]},{"speaker":"L'infirmière","fr":"Il a raison. Regarde le squelette, Tom : le genou est ici. C'est un modèle anatomique.","en":"He's right. Look at the skeleton, Tom: the knee is here. It's an anatomical model.","spans":[[75,85,"fr_anatomique_adj"]]},{"speaker":"Tom","fr":"Et le rhume de Léa, c'est infectieux ? Je ne veux pas tomber malade.","en":"And Léa's cold, is it catching? I don't want to get sick.","spans":[[26,36,"fr_infectieux_adj"]]},{"speaker":"L'infirmière","fr":"Un rhume, ça s'attrape, oui. Lave-toi bien les mains, c'est tout.","en":"A cold is catching, yes. Just wash your hands well.","spans":[]},{"speaker":"Papi Henri","fr":"Moi, je suis insensible au froid… et aux rhumes !","en":"Me, I don't feel the cold… or catch colds!","spans":[[13,23,"fr_insensible_adj"]]}]}],"portraits/terrasse":[{"id":"V_portraits_terrasse_01","title":"Le déjeuner en terrasse","premise":"The family has lunch on the terrace while Tom feeds his baby cousin.","cefr":"C1","lines":[{"speaker":"Maman","fr":"Tom, tu donnes à manger à ta petite cousine ? Quelle maturité !","en":"Tom, you're feeding your little cousin? How grown-up!","spans":[[53,61,"fr_maturite_noun"]]},{"speaker":"Tom","fr":"Elle rit à chaque cuillère. Elle a les yeux bleus, comme oncle Paul.","en":"She laughs at every spoonful. She has blue eyes, like Uncle Paul.","spans":[]},{"speaker":"Papa","fr":"C'est génétique : dans ma famille, presque tout le monde a les yeux bleus.","en":"It's genetic: in my family, almost everyone has blue eyes.","spans":[[6,15,"fr_genetique_adj"]]},{"speaker":"Inès","fr":"Pas dans la mienne ! J'ai des parents adoptifs, alors on ne se ressemble pas.","en":"Not in mine! I have adoptive parents, so we don't look alike.","spans":[[38,46,"fr_adoptif_adj"]]},{"speaker":"Maman","fr":"Mais tu as le même rire que ta maman, c'est sûr.","en":"But you have the same laugh as your mom, that's for sure.","spans":[]},{"speaker":"Papa","fr":"Bon : salade, fruits, poisson grillé. Un repas sain pour un quinquagénaire comme moi !","en":"OK: salad, fruit, grilled fish. A healthy meal for a fiftysomething like me!","spans":[[47,51,"fr_sain_adj"],[60,74,"fr_quinquagenaire_noun"]]},{"speaker":"Tom","fr":"Papa, tu as cinquante ans depuis lundi seulement !","en":"Dad, you've only been fifty since Monday!","spans":[]},{"speaker":"Papa","fr":"Justement. Contre le vieillissement, je mange des légumes.","en":"Exactly. To fight aging, I eat vegetables.","spans":[[21,35,"fr_vieillissement_noun"]]},{"speaker":"Inès","fr":"Regardez dans le bassin : une cane et ses petits ! C'est un canard femelle.","en":"Look in the pool: a duck and her ducklings! It's a female duck.","spans":[[67,74,"fr_femelle_adj"]]}]}],"portraits/anniversaire":[{"id":"V_portraits_anniversaire_01","title":"La fête d'Inès","premise":"At Inès's birthday party, Léa, Tom and their parents talk about the guests.","cefr":"C2","lines":[{"speaker":"Léa","fr":"Maman, regarde tous les cadeaux d'Inès ! C'est une montagne !","en":"Mom, look at all of Inès's presents! It's a mountain!","spans":[]},{"speaker":"Léa","fr":"Et ma part de gâteau est plus petite que celle de Tom. Le partage est inégal !","en":"And my slice of cake is smaller than Tom's. The sharing isn't fair!","spans":[[70,76,"fr_inegal_adj"]]},{"speaker":"Maman","fr":"Ta tante est arrivée avec le bébé. Elle est sortie de la maternité il y a dix jours.","en":"Your aunt is here with the baby. She came home from the maternity ward ten days ago.","spans":[[57,66,"fr_maternite_noun"]]},{"speaker":"Léa","fr":"Il est trop attachant, avec ses toutes petites mains !","en":"He's so sweet, with his tiny little hands!","spans":[[12,21,"fr_attachant_adj"]]},{"speaker":"Papa","fr":"Attention, Léa ! Ne saute pas sur la balançoire comme ça. Tu es trop impulsive.","en":"Careful, Léa! Don't jump on the swing like that. You're too impulsive.","spans":[[69,78,"fr_impulsif_adj"]]},{"speaker":"Léa","fr":"Je suis audacieuse, Papa, ce n'est pas pareil !","en":"I'm daring, Dad, that's not the same!","spans":[[8,18,"fr_audacieux_adj"]]},{"speaker":"Tom","fr":"Moi, je trouve les jeux de ballons un peu infantiles.","en":"I think the balloon games are a little babyish.","spans":[[42,52,"fr_infantile_adj"]]},{"speaker":"Maman","fr":"Tu as onze ans, Tom, pas quarante ! Et range ce téléphone : il est omniprésent, même à une fête.","en":"You're eleven, Tom, not forty! And put that phone away: it's everywhere, even at a party.","spans":[[67,78,"fr_omnipresent_adj"]]}]}],"portraits/gym":[{"id":"V_portraits_gym_01","title":"Papi à la salle de gym","premise":"Grandpa Henri tries the old gym with Tom.","cefr":"C1","lines":[{"speaker":"Tom","fr":"Papi, tu es sûr ? Ces haltères roses sont pour les enfants !","en":"Grandpa, are you sure? Those pink dumbbells are for kids!","spans":[]},{"speaker":"Papi Henri","fr":"Je suis frêle, mais je suis têtu. Je commence petit.","en":"I may be frail, but I'm stubborn. I'm starting small.","spans":[[8,13,"fr_frele_adj"]]},{"speaker":"Tom","fr":"Regarde le monsieur au maillot rayé : il soulève deux grands-mères sur sa barre !","en":"Look at the man in the striped leotard: he's lifting two grandmas on his barbell!","spans":[]},{"speaker":"Papi Henri","fr":"Quelle force musculaire ! Moi, je vais grimper à la corde… enfin, la regarder.","en":"What muscle power! As for me, I'll climb the rope… well, look at it.","spans":[[13,23,"fr_musculaire_adj"]]},{"speaker":"Tom","fr":"Elle est bien verticale, cette corde. Tu pourrais tomber.","en":"That rope is very vertical. You could fall.","spans":[[14,23,"fr_vertical_adj"]]},{"speaker":"Papi Henri","fr":"Alors je vais aux barres parallèles. Elles sont basses, au moins.","en":"Then I'll go to the parallel bars. At least they're low.","spans":[[25,35,"fr_parallele_adj"]]},{"speaker":"Tom","fr":"Papi, tu as encore ton tic : tu remontes tes lunettes toutes les deux secondes.","en":"Grandpa, you've got your habit again: you push up your glasses every two seconds.","spans":[[23,26,"fr_tic_noun"]]},{"speaker":"Papi Henri","fr":"C'est pour mieux te voir ! Range ton sac dans le casier. Heureusement, il est compact.","en":"All the better to see you! Put your bag in the locker. Luckily, it's compact.","spans":[[78,85,"fr_compact_adj"]]}]}],"portraits/salon":[{"id":"V_portraits_salon_01","title":"L'heure du thé","premise":"Mom and Dad have tea in an elegant tea salon where Karim works as a waiter.","cefr":"C2","lines":[{"speaker":"Karim","fr":"Bonjour, milady ! Je plaisante, madame. Une table pour deux ?","en":"Hello, milady! Just kidding, ma'am. A table for two?","spans":[[9,15,"fr_milady_noun"]]},{"speaker":"Maman","fr":"Oui, merci, Karim. Quel salon élégant ! C'est un peu snob, non ?","en":"Yes, thank you, Karim. What an elegant salon! It's a little snobby, isn't it?","spans":[[53,57,"fr_snob_adj"]]},{"speaker":"Karim","fr":"Un peu. Regardez le monsieur au monocle : il sent ses biscuits avant de les manger.","en":"A little. Look at the man with the monocle: he sniffs his cookies before he eats them.","spans":[]},{"speaker":"Papa","fr":"Il a l'air arrogant. Et il parle au maître d'hôtel d'un ton méprisant.","en":"He looks arrogant. And he talks to the head waiter in a scornful tone.","spans":[[11,19,"fr_arrogant_adj"],[60,69,"fr_meprisant_adj"]]},{"speaker":"Karim","fr":"Il est toujours comme ça. Mais il laisse un bon pourboire.","en":"He's always like that. But he leaves a good tip.","spans":[]},{"speaker":"Maman","fr":"Et la dame en lilas ? Elle est distante, elle ne regarde personne.","en":"And the lady in lilac? She's distant, she doesn't look at anyone.","spans":[[31,39,"fr_distant_adj"]]},{"speaker":"Karim","fr":"C'est ma grand-tante ! Elle est timide, c'est tout.","en":"That's my great-aunt! She's shy, that's all.","spans":[]},{"speaker":"Papa","fr":"Oups ! Pardon… Bon, l'addition ne sera pas malhonnête, j'espère ?","en":"Oops! Sorry… Well, I hope the check won't be a rip-off?","spans":[[43,53,"fr_malhonnete_adj"]]},{"speaker":"Karim","fr":"Jamais ! Et le peintre au grand chapeau, là-bas, c'est un vrai bohémien : il paie avec des dessins.","en":"Never! And the painter in the big hat over there is a real free spirit: he pays with drawings.","spans":[[63,71,"fr_bohemien_noun"]]}]}],"portraits/serre":[{"id":"V_portraits_serre_01","title":"La citrouille géante","premise":"Grandpa Henri, Léa and Tom visit the glass conservatory.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Papi, regarde la citrouille du jardinier ! Elle est énorme !","en":"Grandpa, look at the gardener's pumpkin! It's huge!","spans":[]},{"speaker":"Papi Henri","fr":"La terre de cette serre est très fertile. Tout pousse vite, ici.","en":"The soil in this greenhouse is very rich. Everything grows fast here.","spans":[[33,40,"fr_fertile_adj"]]},{"speaker":"Léa","fr":"Même les fougères ! C'est dense comme une jungle, je ne vois plus Tom.","en":"Even the ferns! It's as thick as a jungle, I can't see Tom anymore.","spans":[[26,31,"fr_dense_adj"]]},{"speaker":"Tom","fr":"Je suis là, derrière les palmiers !","en":"I'm here, behind the palm trees!","spans":[]},{"speaker":"Papi Henri","fr":"Venez, les enfants. Le marchand ambulant passe devant la serre avec ses glaces.","en":"Come on, kids. The ice cream vendor is going past the greenhouse with his cart.","spans":[[32,40,"fr_ambulant_adj"]]},{"speaker":"Léa","fr":"Une glace à la citrouille ?","en":"A pumpkin ice cream?","spans":[]},{"speaker":"Papi Henri","fr":"Ha ha ! À la vanille, plutôt.","en":"Ha ha! Vanilla, more like.","spans":[]}]}],"portraits/concours":[{"id":"V_portraits_concours_01","title":"Le concours d'animaux","premise":"Léa and Inès enter their pets in the village pet show.","cefr":"B2","lines":[{"speaker":"Inès","fr":"Mon poney refuse le tutu rose. Il est têtu comme une mule !","en":"My pony won't wear the pink tutu. He's as stubborn as a mule!","spans":[[38,42,"fr_tetu_adj"]]},{"speaker":"Léa","fr":"Et Biscuit dort sur la paille. Le concours le laisse complètement indifférent.","en":"And Biscuit is asleep on the straw. He couldn't care less about the show.","spans":[[66,77,"fr_indifferent_adj"]]},{"speaker":"Inès","fr":"Il est un peu passif, ton chien.","en":"Your dog is a little passive.","spans":[[14,20,"fr_passif_adj"]]},{"speaker":"Léa","fr":"Il est calme ! Ce n'est pas pareil.","en":"He's calm! That's not the same.","spans":[]},{"speaker":"Mme Lefort","fr":"Bonjour, les filles ! Le jury passe dans cinq minutes. Vous êtes prêtes ?","en":"Hello, girls! The judges come by in five minutes. Are you ready?","spans":[]},{"speaker":"Inès","fr":"Oui ! Moi, je suis très enthousiaste. Mon poney, beaucoup moins.","en":"Yes! I'm very excited. My pony, much less so.","spans":[[24,36,"fr_enthousiaste_adj"]]},{"speaker":"Mme Lefort","fr":"Et ce chat qui garde toutes les croquettes pour lui ? Quel égoïste !","en":"And that cat keeping all the kibble for himself? How selfish!","spans":[[59,66,"fr_egoiste_adj"]]},{"speaker":"Léa","fr":"C'est le chat de Tom. Heureusement, le vétérinaire a été prompt : il a déjà soigné la patte du lapin.","en":"That's Tom's cat. Luckily the vet was quick: he's already treated the rabbit's paw.","spans":[[57,63,"fr_prompt_adj"]]}]}],"portraits/tente":[{"id":"V_portraits_tente_01","title":"La tente des gâteaux","premise":"The bakers run the cake tent at the village fair.","cefr":"C2","lines":[{"speaker":"Mme Roux","fr":"Bienvenue à la tente des gâteaux ! L'ambiance est conviviale, non ?","en":"Welcome to the cake tent! It's a friendly atmosphere, isn't it?","spans":[[50,60,"fr_convivial_adj"]]},{"speaker":"Léa","fr":"Oui ! Et ces petits gâteaux roses sont trop craquants !","en":"Yes! And those little pink cupcakes are too cute!","spans":[[44,53,"fr_craquant_adj"]]},{"speaker":"M. Roux","fr":"Attention, un écureuil vient de voler un cupcake !","en":"Watch out, a squirrel just stole a cupcake!","spans":[]},{"speaker":"Léa","fr":"Il est craquant, lui aussi… mais c'est un voleur.","en":"He's cute too… but he's a thief.","spans":[[7,15,"fr_craquant_adj"]]},{"speaker":"Mme Roux","fr":"Alors, Léa : le gâteau au chocolat de M. Roux ou la tarte de Mme Petit ?","en":"So, Léa: Mr. Roux's chocolate cake or Mrs. Petit's pie?","spans":[]},{"speaker":"M. Roux","fr":"Ils ne sont pas comparables. Le mien est incomparable !","en":"They can't be compared. Mine is beyond compare!","spans":[[16,27,"fr_comparable_adj"],[41,53,"fr_incomparable_adj"]]},{"speaker":"Mme Roux","fr":"Quelle modestie ! Bon, Léa, c'est deux euros la part.","en":"How modest! OK, Léa, it's two euros a slice.","spans":[]}]}],"portraits/atelier":[{"id":"V_portraits_atelier_01","title":"À l'atelier","premise":"The children build small wooden projects with Mr. Blanc in the crafts workshop.","cefr":"C2","lines":[{"speaker":"M. Blanc","fr":"Bravo, Inès ! Tu es habile : ton petit bateau est parfaitement lisse.","en":"Great job, Inès! You're skillful: your little boat is perfectly smooth.","spans":[[20,26,"fr_habile_adj"]]},{"speaker":"Inès","fr":"Merci ! Léa et moi, on le fait ensemble. On est inséparables.","en":"Thanks! Léa and I are making it together. We're inseparable.","spans":[[48,60,"fr_inseparable_adj"]]},{"speaker":"M. Blanc","fr":"Et toi, Tom, ton tiroir glisse bien ?","en":"And you, Tom, does your drawer slide well?","spans":[]},{"speaker":"Tom","fr":"Oui ! Je suis adroit avec les tiroirs… mais pas avec les clous.","en":"Yes! I'm good with drawers… but not with nails.","spans":[[14,20,"fr_adroit_adj"]]},{"speaker":"M. Blanc","fr":"Et qui a trié toutes les vis par taille ? C'est très méthodique.","en":"And who sorted all the screws by size? That's very methodical.","spans":[[53,63,"fr_methodique_adj"]]},{"speaker":"Léa","fr":"C'est moi ! Et ce gros carton volumineux, c'est pour qui ?","en":"Me! And that big bulky box, who's it for?","spans":[[30,40,"fr_volumineux_adj"]]},{"speaker":"M. Blanc","fr":"Pour Max, mon chien. Ce fainéant dort dedans toute la journée !","en":"For Max, my dog. That lazybones sleeps in it all day!","spans":[[24,32,"fr_faineant_noun"]]},{"speaker":"Tom","fr":"Et si on cachait le marteau de M. Blanc dans le carton ?","en":"What if we hid Mr. Blanc's hammer in the box?","spans":[]},{"speaker":"Inès","fr":"Tom, tu es malicieux ! Il va le chercher pendant une heure.","en":"Tom, you're mischievous! He'll look for it for an hour.","spans":[[11,20,"fr_malicieux_adj"]]}]}],"portraits/chapelle":[{"id":"V_portraits_chapelle_01","title":"Le baptême du petit Jules","premise":"The family attends a baby's baptism in the village chapel.","cefr":"C1","lines":[{"speaker":"Père Antoine","fr":"Bienvenue à tous. Aujourd'hui, nous accueillons un nouveau-né, le petit Jules.","en":"Welcome, everyone. Today we welcome a newborn, little Jules.","spans":[[51,61,"fr_nouveau_ne_noun"]]},{"speaker":"Maman","fr":"Léa, c'est un moment solennel. On parle tout bas.","en":"Léa, this is a solemn moment. We speak very quietly.","spans":[[21,29,"fr_solennel_adj"]]},{"speaker":"Léa","fr":"D'accord… Papi est très pieux : il connaît tous les chants.","en":"OK… Grandpa is very devout: he knows all the hymns.","spans":[[24,29,"fr_pieux_adj"]]},{"speaker":"Papi Henri","fr":"Pas tous ! Mais j'aime chanter avec les enfants de la chorale.","en":"Not all of them! But I love singing with the children's choir.","spans":[]},{"speaker":"Maman","fr":"La dame au pupitre a été éloquente. Tout le monde l'a écoutée.","en":"The lady at the lectern was eloquent. Everyone listened to her.","spans":[[25,34,"fr_eloquent_adj"]]},{"speaker":"Léa","fr":"Et le monsieur au manteau gris, qui a ouvert la porte à tout le monde ?","en":"And the man in the gray coat who held the door for everyone?","spans":[]},{"speaker":"Maman","fr":"Je ne le connais pas, mais c'est un vrai gentilhomme.","en":"I don't know him, but he's a real gentleman.","spans":[[41,52,"fr_gentilhomme_noun"]]},{"speaker":"Père Antoine","fr":"Notre chapelle est sobre, mais ici, tout le monde est le bienvenu.","en":"Our chapel is plain, but everyone is welcome here.","spans":[[19,24,"fr_sobre_adj"]]},{"speaker":"Papi Henri","fr":"Et le Père Antoine est tolérant : il sourit même quand le bébé pleure !","en":"And Father Antoine is patient: he even smiles when the baby cries!","spans":[[23,31,"fr_tolerant_adj"]]}]}],"portraits/noces":[{"id":"V_portraits_noces_01","title":"Le mariage de Julien et Sophie","premise":"Julien the mailman and Sophie from the post office get married at the town hall.","cefr":"B2","lines":[{"speaker":"Mme Lefort","fr":"Mesdames et messieurs, bienvenue à la mairie pour le mariage de Julien et Sophie !","en":"Ladies and gentlemen, welcome to the town hall for the wedding of Julien and Sophie!","spans":[]},{"speaker":"Papi Henri","fr":"Regarde Julien, Claire : il est tout ému.","en":"Look at Julien, Claire: he's so moved.","spans":[]},{"speaker":"Maman","fr":"Et Sophie est rayonnante. Sa robe est simple, mais irrésistible.","en":"And Sophie is glowing. Her dress is simple, but irresistible.","spans":[[51,63,"fr_irresistible_adj"]]},{"speaker":"Papi Henri","fr":"Julien est un garçon loyal. En dix ans, il n'a jamais perdu une seule lettre !","en":"Julien is a loyal young man. In ten years, he's never lost a single letter!","spans":[[21,26,"fr_loyal_adj"]]},{"speaker":"Maman","fr":"Et humble, avec ça : il dit toujours que c'est grâce à son vélo.","en":"And humble, too: he always says it's thanks to his bike.","spans":[[3,9,"fr_humble_adj"]]},{"speaker":"Mme Lefort","fr":"Avant les signatures, je devrais vous lire tout le régime matrimonial… mais je vous l'épargne !","en":"Before the signatures, I should read you the whole marriage contract… but I'll spare you!","spans":[[58,69,"fr_matrimonial_adj"]]},{"speaker":"Léa","fr":"Papi, le garçon là-bas a rendu un portefeuille perdu au monsieur.","en":"Grandpa, that boy over there gave a lost wallet back to the man.","spans":[]},{"speaker":"Papi Henri","fr":"C'est un geste noble. Très honorable, ce petit !","en":"That's a noble thing to do. A very honorable boy!","spans":[[15,20,"fr_noble_adj"],[27,36,"fr_honorable_adj"]]}]}],"portraits/repetition":[{"id":"V_portraits_repetition_01","title":"Le rideau déchiré","premise":"Mrs. Petit runs the dress rehearsal of the school play.","cefr":"B2","lines":[{"speaker":"Mme Petit","fr":"Silence, s'il vous plaît ! On reprend la scène du château.","en":"Quiet, please! We're taking the castle scene from the top.","spans":[]},{"speaker":"Tom","fr":"Madame, le rideau est déchiré. Qui est volontaire pour le recoudre ?","en":"Ma'am, the curtain is torn. Who'll volunteer to sew it back up?","spans":[[39,49,"fr_volontaire_adj"]]},{"speaker":"Léa","fr":"Moi ! Je suis volontaire.","en":"Me! I'll volunteer.","spans":[[14,24,"fr_volontaire_adj"]]},{"speaker":"Mme Petit","fr":"Merci, Léa. Tom, ton épée est toute molle. On dirait un bâtonnet de fromage !","en":"Thank you, Léa. Tom, your sword is all floppy. It looks like a cheese stick!","spans":[]},{"speaker":"Tom","fr":"Je sais, le résultat est médiocre. Je la refais ce soir.","en":"I know, it came out pretty bad. I'll make it again tonight.","spans":[[25,33,"fr_mediocre_adj"]]},{"speaker":"Mme Petit","fr":"Et ce rôle est très physique : tu dois sauter du trône. Échauffe-toi bien !","en":"And this part is very physical: you have to jump off the throne. Warm up well!","spans":[[20,28,"fr_physique_adj"]]},{"speaker":"Léa","fr":"Madame, Inès a un besoin pressant. Elle peut sortir ?","en":"Ma'am, Inès really needs to go to the bathroom. Can she step out?","spans":[[25,33,"fr_pressant_adj"]]},{"speaker":"Mme Petit","fr":"Bien sûr. Vas-y, Inès ! Les autres, on garde notre énergie.","en":"Of course. Go ahead, Inès! The rest of you, save your energy.","spans":[]},{"speaker":"Tom","fr":"Et notre salaire de comédiens ?","en":"And what about our pay as actors?","spans":[]},{"speaker":"Mme Petit","fr":"Un bonbon chacun. C'est dérisoire, je sais ! Et à la fin, on salue le public avec un sourire cordial.","en":"One piece of candy each. It's next to nothing, I know! And at the end, we bow to the audience with a warm smile.","spans":[[24,33,"fr_derisoire_adj"],[93,100,"fr_cordial_adj"]]}]}],"portraits/garde":[{"id":"V_portraits_garde_01","title":"Les robes identiques","premise":"Léa, Inès and Tom try on outfits for a family party in the dressing room.","cefr":"B2","lines":[{"speaker":"Léa","fr":"Inès, on a des robes identiques ! Tout le monde va nous prendre pour des jumelles.","en":"Inès, we have the same dress! Everyone will think we're twins.","spans":[[21,31,"fr_identique_adj"]]},{"speaker":"Inès","fr":"Super ! Et Tom, il porte quoi ?","en":"Great! And what's Tom wearing?","spans":[]},{"speaker":"Tom","fr":"Ce pull avec un bonhomme de neige. Il est moche, non ?","en":"This sweater with a snowman on it. It's ugly, right?","spans":[[42,47,"fr_moche_adj"]]},{"speaker":"Maman","fr":"Un peu moche, c'est vrai. Mais c'est un cadeau de ta tante, alors tu le gardes ce soir.","en":"A little ugly, that's true. But it's a present from your aunt, so you're wearing it tonight.","spans":[[7,12,"fr_moche_adj"]]},{"speaker":"Léa","fr":"Et la veste du mannequin n'a qu'une seule manche !","en":"And the jacket on the mannequin only has one sleeve!","spans":[]},{"speaker":"Maman","fr":"C'est un travail partiel : la couturière la finit demain.","en":"It's only partly done: the seamstress is finishing it tomorrow.","spans":[[17,24,"fr_partiel_adj"]]},{"speaker":"Tom","fr":"Qui a mangé tous les éclairs ? Il reste un maigre éclair pour quatre !","en":"Who ate all the éclairs? There's one measly éclair left for four of us!","spans":[[43,49,"fr_maigre_adj"]]},{"speaker":"Léa","fr":"C'est le cousin Paul. Il est vraiment gourmand !","en":"It's cousin Paul. He really has a sweet tooth!","spans":[[38,46,"fr_gourmand_adj"]]},{"speaker":"Inès","fr":"Regardez-moi dans ma robe dorée ! C'est un jour glorieux !","en":"Look at me in my golden dress! It's a glorious day!","spans":[[48,56,"fr_glorieux_adj"]]}]}],"portraits/the":[{"id":"V_portraits_the_01","title":"Le chocolat chaud de Léa","premise":"Mrs. Roux takes Léa to the tea room, where Karim serves them.","cefr":"B2","lines":[{"speaker":"Karim","fr":"Votre chocolat chaud, Léa. Avec beaucoup de crème !","en":"Your hot chocolate, Léa. With lots of cream!","spans":[]},{"speaker":"Léa","fr":"Merci, Karim ! Tu es généreux.","en":"Thanks, Karim! You're generous.","spans":[[21,29,"fr_genereux_adj"]]},{"speaker":"Mme Roux","fr":"Karim, votre café est équitable ? Je n'achète plus que ça.","en":"Karim, is your coffee fair trade? That's all I buy now.","spans":[[22,31,"fr_equitable_adj"]]},{"speaker":"Karim","fr":"Oui, madame. Le patron y tient beaucoup.","en":"Yes, ma'am. The owner cares a lot about it.","spans":[]},{"speaker":"Mme Roux","fr":"C'est une maison respectable.","en":"It's a respectable place.","spans":[[17,28,"fr_respectable_adj"]]},{"speaker":"Léa","fr":"Madame Roux, le baromètre indique le soleil. Le temps est favorable à la promenade !","en":"Mrs. Roux, the barometer points to sunny. The weather's good for a walk!","spans":[[58,67,"fr_favorable_adj"]]},{"speaker":"Mme Roux","fr":"Alors je suis obligée de finir mon thé vite !","en":"Then I'll have to finish my tea quickly!","spans":[[14,21,"fr_oblige_adj"]]},{"speaker":"Karim","fr":"Et goûtez ce gâteau : il est coupé à la règle. Du travail de professionnel !","en":"And try this cake: it's cut with a ruler. Professional work!","spans":[[61,74,"fr_professionnel_adj"]]}]}],"portraits/veranda":[{"id":"V_portraits_veranda_01","title":"Les photos de Papi","premise":"On the glass veranda, Grandpa Henri shows the family his old photos.","cefr":"B2","lines":[{"speaker":"Papi Henri","fr":"Venez voir mes vieilles photos, les enfants !","en":"Come see my old photos, kids!","spans":[]},{"speaker":"Tom","fr":"Encore ? Papi, ton diaporama est un peu ennuyeux…","en":"Again? Grandpa, your slideshow is a little boring…","spans":[[40,48,"fr_ennuyeux_adj"]]},{"speaker":"Papi Henri","fr":"Regarde celle-ci : c'est moi pendant mon adolescence, à Marseille.","en":"Look at this one: it's me as a teenager, in Marseille.","spans":[[41,52,"fr_adolescence_noun"]]},{"speaker":"Léa","fr":"Avec tes cheveux longs ! Tu étais un vrai gosse.","en":"With your long hair! You were just a kid.","spans":[[42,47,"fr_gosse_noun"]]},{"speaker":"Papi Henri","fr":"J'avais seize ans. Et voilà notre chat de l'époque, un gros mâle roux.","en":"I was sixteen. And here's our cat from back then, a big orange tomcat.","spans":[[60,64,"fr_male_noun"]]},{"speaker":"Tom","fr":"Il est encore vivant ?","en":"Is he still alive?","spans":[[14,20,"fr_vivant_noun"]]},{"speaker":"Papi Henri","fr":"Oh non, c'était il y a cinquante ans ! Mais il a vécu très longtemps.","en":"Oh no, that was fifty years ago! But he lived a very long time.","spans":[]},{"speaker":"Maman","fr":"Ton chocolat chaud habituel, Papa ?","en":"Your usual hot chocolate, Dad?","spans":[[19,27,"fr_habituel_adj"]]},{"speaker":"Papi Henri","fr":"Oui, merci, ma chérie. Je te suis très reconnaissant.","en":"Yes, thank you, sweetheart. I'm very grateful.","spans":[[39,52,"fr_reconnaissant_adj"]]},{"speaker":"Papi Henri","fr":"Et voilà Inès et ses parents ! Entrez, vous êtes toujours les bienvenus ici.","en":"And here come Inès and her parents! Come in, you're always welcome here.","spans":[[62,71,"fr_bienvenu_noun"]]}]}],"portraits/cartes":[{"id":"V_portraits_cartes_01","title":"L'après-midi géographie","premise":"The family spends a geography afternoon in the map room.","cefr":"B2","lines":[{"speaker":"Maman","fr":"Ce soir, on fait des pancakes au sirop d'érable. C'est une recette canadienne !","en":"Tonight we're making pancakes with maple syrup. It's a Canadian recipe!","spans":[[67,77,"fr_canadien_adj"]]},{"speaker":"Tom","fr":"Comme notre voisin Antoine : il est originaire de Montréal.","en":"Like our neighbor Antoine: he's from Montreal.","spans":[[36,46,"fr_originaire_adj"]]},{"speaker":"Léa","fr":"Et Karim ? Sa famille vient d'où ?","en":"And Karim? Where is his family from?","spans":[]},{"speaker":"Papa","fr":"Il est issu d'une famille algérienne. Montre-moi l'Algérie sur la carte, Léa.","en":"He comes from an Algerian family. Show me Algeria on the map, Léa.","spans":[[7,11,"fr_issu_adj"]]},{"speaker":"Léa","fr":"Ici, en Afrique du Nord ! Et il fait un couscous délicieux.","en":"Here, in North Africa! And he makes delicious couscous.","spans":[]},{"speaker":"Maman","fr":"La cuisine maghrébine, c'est la préférée de Papa.","en":"North African food is Dad's favorite.","spans":[[11,21,"fr_maghrebin_adj"]]},{"speaker":"Tom","fr":"Moi, je veux voir les bus rouges londoniens. On va à Londres cet été ?","en":"I want to see the red London buses. Are we going to London this summer?","spans":[[33,43,"fr_londonien_adj"]]},{"speaker":"Papa","fr":"Peut-être ! Trouve d'abord Londres sur la carte.","en":"Maybe! First find London on the map.","spans":[]},{"speaker":"Tom","fr":"Facile : c'est à côté de Big Ben !","en":"Easy: it's next to Big Ben!","spans":[]}]}],"portraits/portraits":[{"id":"C_R_people_01","title":"La nouvelle voisine","premise":"Two neighbors talk about the new woman who moved in next door.","cefr":"A1","lines":[{"speaker":"M. Petit","fr":"Bonjour madame ! Vous avez vu ? Il y a une nouvelle voisine.","en":"Hello, madam! Have you seen? There's a new neighbor.","spans":[[8,14,"fr_madame_noun"]]},{"speaker":"Mme Roux","fr":"Oui, une dame très élégante. Elle s'appelle madame Laval.","en":"Yes, a very elegant lady. She's called Mrs. Laval.","spans":[[9,13,"fr_dame_noun"],[44,50,"fr_madame_noun"]]},{"speaker":"M. Petit","fr":"Elle vit seule ?","en":"Does she live alone?","spans":[]},{"speaker":"Mme Roux","fr":"Non, avec son mari. Un homme très grand, avec une moustache.","en":"No, with her husband. A very tall man, with a mustache.","spans":[[23,28,"fr_homme_noun"]]},{"speaker":"M. Petit","fr":"Ah, c'est ce monsieur que j'ai vu ce matin.","en":"Ah, that's the gentleman I saw this morning.","spans":[[13,21,"fr_monsieur_noun"]]},{"speaker":"Mme Roux","fr":"Oui. C'est une femme très gentille. Elle m'a apporté des fleurs.","en":"Yes. She's a very nice woman. She brought me flowers.","spans":[[15,20,"fr_femme_noun"]]},{"speaker":"M. Petit","fr":"Les gens du quartier sont contents.","en":"The people in the neighborhood are pleased.","spans":[[4,8,"fr_gens_noun"]]},{"speaker":"Mme Roux","fr":"On pourrait l'inviter à la fête des voisins.","en":"We could invite her to the street party.","spans":[[36,43,"fr_voisin_noun"]]},{"speaker":"M. Petit","fr":"Bonne idée. C'est une personne charmante.","en":"Good idea. She's a charming person.","spans":[[22,30,"fr_personne_noun"]]},{"speaker":"Mme Roux","fr":"Je lui en parle demain.","en":"I'll mention it to her tomorrow.","spans":[]}]}],"portraits/ages":[{"id":"C_R_people_02","title":"La fête du village","premise":"An old resident and a young man chat at the village festival.","cefr":"A1","lines":[{"speaker":"M. Fabre","fr":"Regarde cette foule ! Tout le village est là.","en":"Look at this crowd! The whole village is here.","spans":[]},{"speaker":"Simon","fr":"Combien d'habitants il y a, ici ?","en":"How many people live here?","spans":[[10,19,"fr_habitant_noun"]]},{"speaker":"M. Fabre","fr":"Mille deux cents. Quand j'étais enfant, il y en avait trois mille.","en":"Twelve hundred. When I was a child, there were three thousand.","spans":[[32,38,"fr_enfant_noun"]]},{"speaker":"Simon","fr":"Les jeunes partent en ville ?","en":"Do young people move to the city?","spans":[]},{"speaker":"M. Fabre","fr":"Oui. La jeunesse cherche du travail. C'est la vie.","en":"Yes. Young people look for work. That's life.","spans":[[8,16,"fr_jeunesse_noun"],[46,49,"fr_vie_noun"]]},{"speaker":"Simon","fr":"Moi, je suis revenu. J'aime trop la campagne.","en":"I've come back. I love the countryside too much.","spans":[]},{"speaker":"M. Fabre","fr":"Bravo, mon garçon ! À ton âge, c'est rare.","en":"Well done, my boy! At your age, that's rare.","spans":[[11,17,"fr_garcon_noun"],[26,29,"fr_age_noun"]]},{"speaker":"Simon","fr":"Et la fête, c'est depuis quand ?","en":"And how long has the festival been going?","spans":[]},{"speaker":"M. Fabre","fr":"Depuis toujours ! C'est la fête du peuple, de tout le monde.","en":"Forever! It's everyone's festival.","spans":[[35,41,"fr_peuple_noun"]]},{"speaker":"Simon","fr":"Alors, on danse !","en":"Then let's dance!","spans":[]}]}],"portraits/palier":[{"id":"C_R_people_03","title":"Le vieux monsieur du parc","premise":"Two mothers talk about an elderly blind man who tells stories in the park.","cefr":"B1","lines":[{"speaker":"Céline","fr":"Tu connais le vieillard qui raconte des histoires aux gosses, sur le banc ?","en":"Do you know the old man who tells stories to the kids, on the bench?","spans":[[14,23,"fr_vieillard_noun"]]},{"speaker":"Amina","fr":"Oui, monsieur André. Il est aveugle, mais il reconnaît chaque môme à sa voix !","en":"Yes, Mr. André. He's blind, but he recognises every kid by their voice!","spans":[[28,35,"fr_aveugle_noun"],[62,66,"fr_mome_noun"]]},{"speaker":"Céline","fr":"C'est incroyable. Mon aîné l'adore.","en":"That's amazing. My eldest adores him.","spans":[[22,26,"fr_aine_noun"]]},{"speaker":"Amina","fr":"Il raconte la vie du quartier, il y a soixante ans.","en":"He tells them about life in the neighborhood sixty years ago.","spans":[]},{"speaker":"Céline","fr":"Il dit qu'à l'époque, il était un petit voyou !","en":"He says he was a little rascal back then!","spans":[]},{"speaker":"Amina","fr":"Ha ha ! Il est plein d'humanité.","en":"Ha ha! He's full of kindness.","spans":[[23,31,"fr_humanite_noun"]]},{"speaker":"Céline","fr":"Il a vu la guerre, aussi. Il dit qu'il est content d'être vivant.","en":"He saw the war, too. He says he's happy to be alive.","spans":[]},{"speaker":"Amina","fr":"On devrait lui apporter un café, demain.","en":"We should bring him a coffee tomorrow.","spans":[]},{"speaker":"Céline","fr":"Bonne idée !","en":"Good idea!","spans":[]}]}],"portraits/jardin":[{"id":"C_R_people_04","title":"La maternité","premise":"A woman visits her friend at the maternity ward after the birth of her baby.","cefr":"C1","lines":[{"speaker":"Pauline","fr":"Élise ! Félicitations ! Il est magnifique, ton nouveau-né.","en":"Élise! Congratulations! Your newborn is gorgeous.","spans":[]},{"speaker":"Élise","fr":"Merci ! Après neuf mois de grossesse, enfin !","en":"Thank you! After nine months of pregnancy, at last!","spans":[[27,36,"fr_grossesse_noun"]]},{"speaker":"Pauline","fr":"Comment tu te sens ?","en":"How do you feel?","spans":[]},{"speaker":"Élise","fr":"Fatiguée, mais heureuse. La maternité, c'est une aventure !","en":"Tired, but happy. Motherhood is an adventure!","spans":[]},{"speaker":"Pauline","fr":"Et Marc ?","en":"And Marc?","spans":[]},{"speaker":"Élise","fr":"Il est parfait. Un vrai gentilhomme : il m'apporte des fleurs chaque jour.","en":"He's perfect. A real gentleman: he brings me flowers every day.","spans":[]},{"speaker":"Pauline","fr":"Il a pris de la maturité !","en":"He's matured!","spans":[]},{"speaker":"Élise","fr":"Ha ha ! Oui. L'hôpital est plein, l'effectif des infirmières est trop petit.","en":"Ha ha! Yes. The hospital is full, there aren't enough nurses.","spans":[]},{"speaker":"Pauline","fr":"Et à l'heure des visites, quelle cohue dans le couloir !","en":"And at visiting time, what a crush in the corridor!","spans":[[33,38,"fr_cohue_noun"]]},{"speaker":"Élise","fr":"Oui ! Ma belle-mère est arrivée avec un chapeau, comme une lady anglaise !","en":"Yes! My mother-in-law turned up in a hat, like an English lady!","spans":[[59,63,"fr_lady_noun"]]}]}],"portraits/caracteres":[{"id":"C_R_character_01","title":"La nouvelle collègue","premise":"Two colleagues talk about a new team member.","cefr":"A2","lines":[{"speaker":"Maxime","fr":"Tu as rencontré la nouvelle collègue ?","en":"Have you met the new colleague?","spans":[]},{"speaker":"Laurence","fr":"Oui, elle est charmante. Et très compétente.","en":"Yes, she's charming. And very competent.","spans":[[14,23,"fr_charmant_adj"]]},{"speaker":"Maxime","fr":"Elle va être notre principale contact avec les clients.","en":"She's going to be our main contact with the clients.","spans":[[19,29,"fr_principal_adj"]]},{"speaker":"Laurence","fr":"Super. Elle a un talent unique pour les chiffres.","en":"Great. She has a unique talent for figures.","spans":[[24,30,"fr_unique_adj"]]},{"speaker":"Maxime","fr":"Et elle est précise : chaque rapport est exact.","en":"And she's precise: every report is spot on.","spans":[[41,46,"fr_exact_adj"]]},{"speaker":"Laurence","fr":"Elle est contente d'être ici ?","en":"Is she happy to be here?","spans":[[9,17,"fr_content_adj"]]},{"speaker":"Maxime","fr":"Oui, elle est fière d'avoir eu ce poste.","en":"Yes, she's proud to have got this job.","spans":[[14,19,"fr_fier_adj"]]},{"speaker":"Laurence","fr":"Et sur le plan personnel ?","en":"And on a personal level?","spans":[[15,24,"fr_personnel_adj"]]},{"speaker":"Maxime","fr":"Très humaine, très sympa. Elle a apporté des croissants ce matin !","en":"Very warm, very nice. She brought croissants this morning!","spans":[[5,12,"fr_humain_adj"]]},{"speaker":"Laurence","fr":"Alors, je l'adore déjà !","en":"Then I love her already!","spans":[]}]}],"portraits/attente":[{"id":"C_R_character_02","title":"L'attente chez le médecin","premise":"Two patients chat in a crowded doctor's waiting room.","cefr":"B2","lines":[{"speaker":"une patiente","fr":"Ça fait une heure qu'on attend ! Je suis pressée, moi.","en":"We've been waiting for an hour! I'm in a hurry.","spans":[[41,48,"fr_presse_adj"]]},{"speaker":"M. Morin","fr":"Moi aussi. Je suis très impatient.","en":"Me too. I'm very impatient.","spans":[[24,33,"fr_impatient_adj"]]},{"speaker":"une patiente","fr":"C'est ennuyeux, cette salle d'attente. Pas de magazines !","en":"This waiting room is boring. No magazines!","spans":[]},{"speaker":"M. Morin","fr":"Regardez ce petit garçon, il est maladroit avec son jouet.","en":"Look at that little boy, he's clumsy with his toy.","spans":[[33,42,"fr_maladroit_adj"]]},{"speaker":"une patiente","fr":"Ha ha ! Il est irrésistible.","en":"Ha ha! He's irresistible.","spans":[]},{"speaker":"M. Morin","fr":"Sa mère a l'air désespérée, il court partout.","en":"His mother looks desperate, he's running everywhere.","spans":[[16,26,"fr_desespere_adj"]]},{"speaker":"une patiente","fr":"Le prix de la consultation a encore augmenté.","en":"The price of the appointment has gone up again.","spans":[]},{"speaker":"M. Morin","fr":"Oui, et le remboursement est dérisoire !","en":"Yes, and the refund is pitiful!","spans":[]},{"speaker":"une patiente","fr":"Ah, c'est mon tour !","en":"Ah, it's my turn!","spans":[]},{"speaker":"M. Morin","fr":"Bonne chance !","en":"Good luck!","spans":[]}]}],"portraits/jeux":[{"id":"C_R_character_03","title":"Le chat têtu","premise":"A woman tells her friend about her stubborn cat.","cefr":"B2","lines":[{"speaker":"Margot","fr":"Mon chat est tellement têtu ! Il refuse sa nouvelle nourriture.","en":"My cat is so stubborn! He refuses his new food.","spans":[]},{"speaker":"Jeanne","fr":"Il est malin, il attend que tu lui donnes du poulet !","en":"He's clever, he's waiting for you to give him chicken!","spans":[]},{"speaker":"Margot","fr":"Exactement. Et quand je lui parle, il est indifférent.","en":"Exactly. And when I talk to him, he couldn't care less.","spans":[]},{"speaker":"Jeanne","fr":"C'est le caractère des chats.","en":"That's what cats are like.","spans":[]},{"speaker":"Margot","fr":"Hier, il a cassé un verre et il n'était même pas honteux !","en":"Yesterday he broke a glass and he wasn't even ashamed!","spans":[]},{"speaker":"Jeanne","fr":"Ha ha ! Et sa voix ? Tu disais qu'il miaulait bizarrement.","en":"Ha ha! And his voice? You said he was meowing strangely.","spans":[]},{"speaker":"Margot","fr":"Oui, un miaulement rauque, c'est inhabituel.","en":"Yes, a hoarse meow, it's unusual.","spans":[[19,25,"fr_rauque_adj"],[33,43,"fr_inhabituel_adj"]]},{"speaker":"Jeanne","fr":"Tu devrais l'emmener chez le vétérinaire.","en":"You should take him to the vet.","spans":[]},{"speaker":"Margot","fr":"Le soi-disant « meilleur vétérinaire » du quartier est en vacances !","en":"The so-called \"best vet\" in the area is on vacation!","spans":[]},{"speaker":"Jeanne","fr":"Va voir la jeune vétérinaire, place de la mairie. Elle a soigné mon chien cardiaque.","en":"Go and see the young vet on the town-hall square. She treated my dog with the heart problem.","spans":[]},{"speaker":"Margot","fr":"Merci !","en":"Thanks!","spans":[]}]}],"portraits/salle":[{"id":"C_R_character_04","title":"Le nouveau voisin","premise":"An elderly woman tells her daughter about a kind new neighbor.","cefr":"B1","lines":[{"speaker":"Maman","fr":"Le nouveau voisin est très aimable. Il m'a aidée à porter mes courses.","en":"The new neighbor is very kind. He helped me carry my shopping.","spans":[[27,34,"fr_aimable_adj"]]},{"speaker":"Sophie","fr":"C'est gentil ! Il est comment ?","en":"That's nice! What's he like?","spans":[]},{"speaker":"Maman","fr":"Chaleureux et sincère. Il sourit toujours.","en":"Warm and sincere. He always smiles.","spans":[[0,10,"fr_chaleureux_adj"],[14,21,"fr_sincere_adj"]]},{"speaker":"Sophie","fr":"C'est rare aujourd'hui !","en":"That's rare these days!","spans":[]},{"speaker":"Maman","fr":"Oui. Il est honnête aussi : il m'a rendu un billet de vingt euros que j'avais fait tomber.","en":"Yes. He's honest too: he gave me back a twenty-euro note I'd dropped.","spans":[[12,19,"fr_honnete_adj"]]},{"speaker":"Sophie","fr":"Admirable !","en":"Admirable!","spans":[[0,9,"fr_admirable_adj"]]},{"speaker":"Maman","fr":"Il a des relations très amicales avec tout l'immeuble.","en":"He gets on very well with the whole building.","spans":[[24,32,"fr_amical_adj"]]},{"speaker":"Sophie","fr":"Il fait quoi, comme travail ?","en":"What does he do for a living?","spans":[]},{"speaker":"Maman","fr":"Il est infirmier. Il travaille la nuit, des horaires peu habituels.","en":"He's a nurse. He works nights, unusual hours.","spans":[]},{"speaker":"Sophie","fr":"Tu devrais l'inviter pour un café. Ce serait raisonnable de connaître ses voisins.","en":"You should invite him for a coffee. It's sensible to know your neighbors.","spans":[[45,56,"fr_raisonnable_adj"]]}]}],"portraits/club":[{"id":"C_R_character_05","title":"La cérémonie de remise des diplômes","premise":"Two parents talk at their daughter's graduation ceremony.","cefr":"B2","lines":[{"speaker":"Hélène","fr":"Quelle cérémonie solennelle ! Tous ces diplômés en toge.","en":"What a solemn ceremony! All those graduates in gowns.","spans":[]},{"speaker":"Jacques","fr":"Et notre fille est la première de sa promotion !","en":"And our daughter is top of her year!","spans":[]},{"speaker":"Hélène","fr":"Mais elle reste humble. Elle n'en parle à personne.","en":"But she stays humble. She doesn't tell anyone.","spans":[]},{"speaker":"Jacques","fr":"Elle est trop modeste !","en":"She's too modest!","spans":[[14,21,"fr_modeste_adj"]]},{"speaker":"Hélène","fr":"Le directeur a parlé de sa noble ambition : devenir médecin dans les pays pauvres.","en":"The director talked about her noble ambition: to become a doctor in poor countries.","spans":[]},{"speaker":"Jacques","fr":"C'est un choix très moral.","en":"That's a very principled choice.","spans":[]},{"speaker":"Hélène","fr":"Elle est habile avec les gens. Elle saura gérer un public hostile.","en":"She's skillful with people. She'll know how to handle a hostile audience.","spans":[[58,65,"fr_hostile_adj"]]},{"speaker":"Jacques","fr":"Oui, mais elle doit rester prudente, à l'étranger.","en":"Yes, but she must stay careful abroad.","spans":[[27,35,"fr_prudent_adj"]]},{"speaker":"Hélène","fr":"Regarde, c'est son tour !","en":"Look, it's her turn!","spans":[]},{"speaker":"Jacques","fr":"Bravo, ma fille !","en":"Well done, my girl!","spans":[]}]}],"portraits/bal":[{"id":"C_R_character_06","title":"Le petit aventurier","premise":"Two parents discuss their adventurous young son.","cefr":"C1","lines":[{"speaker":"Lucie","fr":"Tu as vu Tom ? Il a escaladé l'arbre tout seul !","en":"Did you see Tom? He climbed the tree all by himself!","spans":[]},{"speaker":"Romain","fr":"Il est aventureux, ce petit !","en":"He's adventurous, that little one!","spans":[]},{"speaker":"Lucie","fr":"Et précoce : il lit déjà à cinq ans.","en":"And precocious: he's already reading at five.","spans":[]},{"speaker":"Romain","fr":"Mais parfois, son comportement est encore un peu infantile.","en":"But sometimes his behavior is still a bit babyish.","spans":[]},{"speaker":"Lucie","fr":"C'est normal, il est petit ! Il est très spontané.","en":"That's normal, he's little! He's very spontaneous.","spans":[]},{"speaker":"Romain","fr":"Et très affectif : il fait des câlins à tout le monde.","en":"And very affectionate: he hugs everyone.","spans":[]},{"speaker":"Lucie","fr":"Sa maîtresse dit qu'il pose des questions indirectes pour avoir des bonbons !","en":"His teacher says he asks sneaky questions to get candy!","spans":[]},{"speaker":"Romain","fr":"Ha ha ! Malin !","en":"Ha ha! Clever!","spans":[]},{"speaker":"Lucie","fr":"Il a un amour passionnel pour les dinosaures.","en":"He's madly in love with dinosaurs.","spans":[]},{"speaker":"Romain","fr":"Et il veut une petite sœur ! On participe à la croissance démographique ?","en":"And he wants a little sister! Should we contribute to population growth?","spans":[]},{"speaker":"Lucie","fr":"Ha ha ! On en reparle !","en":"Ha ha! We'll talk about it!","spans":[]}]},{"id":"C_R_character_07","title":"Le rendez-vous chez le spécialiste","premise":"A man talks to a specialist doctor about his breathing problems.","cefr":"C1","lines":[{"speaker":"le docteur","fr":"Bonjour, monsieur Gauthier. Vous avez des problèmes respiratoires ?","en":"Hello, Mr. Gauthier. You've got breathing problems?","spans":[]},{"speaker":"M. Gauthier","fr":"Oui, je suis essoufflé quand je monte les escaliers. C'est angoissant.","en":"Yes, I get out of breath when I climb the stairs. It's frightening.","spans":[]},{"speaker":"le docteur","fr":"Il y a des problèmes héréditaires dans votre famille ?","en":"Are there any hereditary problems in your family?","spans":[]},{"speaker":"M. Gauthier","fr":"Mon père avait de l'asthme.","en":"My father had asthma.","spans":[]},{"speaker":"le docteur","fr":"Ce n'est pas incurable. Nous allons faire des tests.","en":"It's not incurable. We'll do some tests.","spans":[]},{"speaker":"M. Gauthier","fr":"Une opération chirurgicale ?","en":"A surgical operation?","spans":[]},{"speaker":"le docteur","fr":"Non, pas du tout. Un simple traitement. Et une vie plus sobre : moins de cigarettes !","en":"No, not at all. Just treatment. And a healthier lifestyle: fewer cigarettes!","spans":[]},{"speaker":"M. Gauthier","fr":"D'accord. Ma femme sera contente.","en":"OK. My wife will be happy.","spans":[]},{"speaker":"le docteur","fr":"Je suis formel : arrêtez de fumer.","en":"I'm adamant: stop smoking.","spans":[]},{"speaker":"M. Gauthier","fr":"C'est un peu humiliant, à mon âge, de me faire gronder !","en":"It's a bit humiliating, at my age, to get told off!","spans":[]},{"speaker":"le docteur","fr":"Ha ha ! C'est pour votre bien.","en":"Ha ha! It's for your own good.","spans":[]}]}],"portraits/musique":[{"id":"C_R_character_08","title":"Le dîner chez les Durand","premise":"A couple walk back to their car after a dinner party with unpleasant hosts.","cefr":"C1","lines":[{"speaker":"Claire","fr":"Quel dîner ! Monsieur Durand était tellement arrogant.","en":"What a dinner! Mr. Durand was so arrogant.","spans":[]},{"speaker":"Antoine","fr":"Oui, et méprisant avec le serveur.","en":"Yes, and contemptuous with the waiter.","spans":[]},{"speaker":"Claire","fr":"Sa femme était distante, elle n'a presque pas parlé.","en":"His wife was distant, she hardly spoke.","spans":[]},{"speaker":"Antoine","fr":"Mais leur fils était très galant : il t'a tenu la porte.","en":"But their son was very gallant: he held the door for you.","spans":[]},{"speaker":"Claire","fr":"Oui, c'était le seul gentil.","en":"Yes, he was the only nice one.","spans":[]},{"speaker":"Antoine","fr":"Et leur maison ! Une décoration extravagante, de l'or partout.","en":"And their house! Extravagant decor, gold everywhere.","spans":[]},{"speaker":"Claire","fr":"Et le chien, avec son regard suppliant pour avoir du gâteau !","en":"And the dog, with its pleading look for cake!","spans":[]},{"speaker":"Antoine","fr":"Ha ha ! Et toi, à la fin, tu avais un air hagard !","en":"Ha ha! And you looked haggard by the end!","spans":[]},{"speaker":"Claire","fr":"Je suis épuisée ! Et toi, tu as bu trop de vin. Conduire, c'est imprudent !","en":"I'm exhausted! And you've drunk too much wine. Driving is reckless!","spans":[]},{"speaker":"Antoine","fr":"Non, juste un verre. Mais tu as raison, prends le volant.","en":"No, just one glass. But you're right, you drive.","spans":[]}]}],"portraits/bibliotheque":[{"id":"C_R_character_09","title":"Le discours de la directrice","premise":"Two teachers talk about the retiring head teacher's farewell speech.","cefr":"C1","lines":[{"speaker":"Mme Royer","fr":"Le discours de la directrice était très éloquent.","en":"The head's speech was very eloquent.","spans":[]},{"speaker":"M. Lemaire","fr":"Oui. Elle a toujours été bienveillante avec nous.","en":"Yes. She was always kind to us.","spans":[]},{"speaker":"Mme Royer","fr":"Et indulgente avec les élèves ! Trop, parfois.","en":"And lenient with the students! Too lenient, sometimes.","spans":[]},{"speaker":"M. Lemaire","fr":"Ha ha ! Mais elle était prompte à réagir quand il y avait un problème.","en":"Ha ha! But she was quick to react when there was a problem.","spans":[]},{"speaker":"Mme Royer","fr":"C'est vrai. Elle était aussi très adroite avec les parents difficiles.","en":"That's true. She was also very skillful with difficult parents.","spans":[]},{"speaker":"M. Lemaire","fr":"Le point saillant de son discours, pour moi : « Une école doit être accueillante. »","en":"The key point of her speech, for me: \"A school must be welcoming.\"","spans":[]},{"speaker":"Mme Royer","fr":"On a été privilégiés de travailler avec elle.","en":"We were privileged to work with her.","spans":[]},{"speaker":"M. Lemaire","fr":"Le nouveau directeur arrive lundi.","en":"The new head arrives on Monday.","spans":[]},{"speaker":"Mme Royer","fr":"J'espère qu'il sera aussi sympa !","en":"I hope he'll be just as nice!","spans":[]}]}],"portraits/apparences":[{"id":"C_R_appearance_01","title":"Les photos de vacances","premise":"Two friends look at vacation photos on a phone.","cefr":"A2","lines":[{"speaker":"Emma","fr":"Regarde mes photos de Grèce ! La mer est magnifique.","en":"Look at my photos of Greece! The sea is gorgeous.","spans":[[41,51,"fr_magnifique_adj"]]},{"speaker":"Chloé","fr":"Oh, quelle jolie plage ! Et ce petit chat, il est trop mignon !","en":"Oh, what a pretty beach! And that little cat is so cute!","spans":[[11,16,"fr_joli_adj"],[55,61,"fr_mignon_adj"]]},{"speaker":"Emma","fr":"Il nous suivait partout. Il était perdu, je crois.","en":"It followed us everywhere. I think it was lost.","spans":[[34,39,"fr_perdu_adj"]]},{"speaker":"Chloé","fr":"C'est qui, le garçon blond à côté de toi ?","en":"Who's the blond boy next to you?","spans":[[21,26,"fr_blond_adj"]]},{"speaker":"Emma","fr":"Mon cousin Lucas. Il est très vif, il veut tout visiter !","en":"My cousin Lucas. He's very lively, he wants to visit everything!","spans":[[30,33,"fr_vif_adj"]]},{"speaker":"Chloé","fr":"Et là, tu as l'air fatiguée.","en":"And here you look tired.","spans":[[19,27,"fr_fatigue_adj"]]},{"speaker":"Emma","fr":"Oui, après la randonnée jusqu'au temple.","en":"Yes, after the hike up to the temple.","spans":[]},{"speaker":"Chloé","fr":"C'est un temple célèbre ?","en":"Is it a famous temple?","spans":[[16,23,"fr_celebre_adj"]]},{"speaker":"Emma","fr":"Oui, le temple de Poséidon !","en":"Yes, the Temple of Poseidon!","spans":[]},{"speaker":"Chloé","fr":"J'ai trop envie d'y aller !","en":"I'm dying to go!","spans":[]}]}],"portraits/voyages":[{"id":"C_R_appearance_02","title":"La classe internationale","premise":"A teacher tells her husband about her new international class.","cefr":"B2","lines":[{"speaker":"Nathalie","fr":"Ma nouvelle classe est très internationale !","en":"My new class is really international!","spans":[]},{"speaker":"Olivier","fr":"Ah oui ? Il y a des élèves de quels pays ?","en":"Really? What countries are the students from?","spans":[]},{"speaker":"Nathalie","fr":"Une petite fille japonaise, un garçon indien, et des jumeaux suédois.","en":"A little Japanese girl, an Indian boy, and Swedish twins.","spans":[[17,26,"fr_japonais_adj"],[38,44,"fr_indien_adj"]]},{"speaker":"Olivier","fr":"Les jumeaux suédois sont blonds ?","en":"Are the Swedish twins blond?","spans":[]},{"speaker":"Nathalie","fr":"Non, roux ! Avec des taches de rousseur.","en":"No, red-haired! With freckles.","spans":[]},{"speaker":"Olivier","fr":"Et les élèves français ?","en":"And the French students?","spans":[]},{"speaker":"Nathalie","fr":"Il y a un garçon breton et une fille basque. Ils se disputent sur la meilleure région !","en":"There's a boy from Brittany and a Basque girl. They argue about which region is best!","spans":[[17,23,"fr_breton_adj"],[37,43,"fr_basque_adj"]]},{"speaker":"Olivier","fr":"Ha ha ! Et tu as une élève issue d'une famille d'artistes, je crois ?","en":"Ha ha! And you've got a student from a family of artists, I think?","spans":[]},{"speaker":"Nathalie","fr":"Oui, elle porte toujours des vêtements mauves !","en":"Yes, she always wears mauve clothes!","spans":[[39,45,"fr_mauve_adj"]]},{"speaker":"Olivier","fr":"Quelle belle classe !","en":"What a lovely class!","spans":[]}]}],"portraits/coiffure":[{"id":"C_R_appearance_03","title":"La nouvelle coupe","premise":"A man shows his friend his new, very short haircut.","cefr":"B2","lines":[{"speaker":"Rémi","fr":"Kevin ! Ta coupe ! Tu as les cheveux ras !","en":"Kevin! Your haircut! Your hair's cropped short!","spans":[[37,40,"fr_ras_adj"]]},{"speaker":"Kevin","fr":"Oui. Le coiffeur était un peu brusque avec la tondeuse...","en":"Yes. The hairdresser was a bit rough with the clippers...","spans":[]},{"speaker":"Rémi","fr":"Ha ha ! Tu as l'air comique !","en":"Ha ha! You look funny!","spans":[[20,27,"fr_comique_adj"]]},{"speaker":"Kevin","fr":"Merci ! Ma copine dit que c'est moche.","en":"Thanks! My girlfriend says it's ugly.","spans":[]},{"speaker":"Rémi","fr":"Non, ça fait plus masculin.","en":"No, it looks more manly.","spans":[]},{"speaker":"Kevin","fr":"Mon père est chauve à cinquante ans. Moi, je prépare l'avenir !","en":"My dad was bald at fifty. I'm preparing for the future!","spans":[[13,19,"fr_chauve_adj"]]},{"speaker":"Rémi","fr":"Et tu es tout maigre maintenant ? Tu fais un régime ?","en":"And you're all skinny now? Are you on a diet?","spans":[]},{"speaker":"Kevin","fr":"Oui, j'ai perdu cinq kilos. Je suis descendu à un poids inférieur à soixante-dix kilos.","en":"Yes, I've lost five kilos. I'm under seventy kilos now.","spans":[]},{"speaker":"Rémi","fr":"Bravo !","en":"Well done!","spans":[]},{"speaker":"Kevin","fr":"Merci !","en":"Thanks!","spans":[]}]}],"portraits/tresors":[{"id":"C_R_appearance_04","title":"Le feu d'artifice","premise":"A family watches the 14th of July fireworks.","cefr":"B1","lines":[{"speaker":"Jade","fr":"Papa, regarde ! C'est spectaculaire !","en":"Dad, look! It's spectacular!","spans":[[22,35,"fr_spectaculaire_adj"]]},{"speaker":"Papa","fr":"Oui, magnifique ! Ces étoiles dorées dans le ciel...","en":"Yes, wonderful! Those golden stars in the sky...","spans":[[30,36,"fr_dore_adj"]]},{"speaker":"Jade","fr":"C'est le plus impressionnant que j'ai vu !","en":"It's the most impressive one I've ever seen!","spans":[[14,28,"fr_impressionnant_adj"]]},{"speaker":"Papa","fr":"C'est étonnant, chaque année ils font mieux.","en":"It's amazing, every year they do better.","spans":[[6,14,"fr_etonnant_adj"]]},{"speaker":"Jade","fr":"On le voit de toute la ville ?","en":"Can you see it from the whole town?","spans":[]},{"speaker":"Papa","fr":"Oui, il est visible depuis la colline.","en":"Yes, it's visible from the hill.","spans":[[12,19,"fr_visible_adj"]]},{"speaker":"Jade","fr":"Celui-là ressemble à une fleur !","en":"That one looks like a flower!","spans":[]},{"speaker":"Papa","fr":"Et l'autre est semblable à une cascade.","en":"And the other one is like a waterfall.","spans":[[15,24,"fr_semblable_adj"]]},{"speaker":"Jade","fr":"C'est fabuleux ! Merci de m'avoir emmenée, Papa.","en":"It's fabulous! Thank you for bringing me, Dad.","spans":[[6,14,"fr_fabuleux_adj"]]},{"speaker":"Papa","fr":"Je suis reconnaissant d'avoir une fille comme toi !","en":"I'm grateful to have a daughter like you!","spans":[]}]}],"portraits/studio":[{"id":"C_R_appearance_05","title":"Le mur d'escalade","premise":"A climbing instructor gives instructions to a beginner on an indoor climbing wall.","cefr":"B2","lines":[{"speaker":"le moniteur","fr":"Ce mur est vertical, mais les prises sont faciles.","en":"This wall is vertical, but the holds are easy.","spans":[]},{"speaker":"Pauline","fr":"Il est très élevé ! Quinze mètres ?","en":"It's really high! Fifteen meters?","spans":[[12,17,"fr_eleve_adj"]]},{"speaker":"le moniteur","fr":"Douze. Tu es bien attachée ? Le harnais est bien monté ?","en":"Twelve. Are you tied in properly? Is your harness on right?","spans":[[49,54,"fr_monte_adj"]]},{"speaker":"Pauline","fr":"Oui, je crois.","en":"Yes, I think so.","spans":[]},{"speaker":"le moniteur","fr":"Garde les pieds parallèles au mur. Et reste lucide, pas de panique.","en":"Keep your feet parallel to the wall. And stay clear-headed, don't panic.","spans":[]},{"speaker":"Pauline","fr":"J'ai les mains insensibles, elles sont froides !","en":"I can't feel my hands, they're cold!","spans":[]},{"speaker":"le moniteur","fr":"Frotte-les avec la magnésie. L'effet est immédiat.","en":"Rub them with chalk. The effect is immediate.","spans":[]},{"speaker":"Pauline","fr":"Voilà, c'est mieux.","en":"There, that's better.","spans":[]},{"speaker":"le moniteur","fr":"L'escalade, c'est un sport sain pour le corps et la tête.","en":"Climbing is a healthy sport for body and mind.","spans":[]},{"speaker":"Pauline","fr":"Allez, je monte !","en":"Here I go!","spans":[]}]}],"portraits/galerie":[{"id":"C_R_appearance_06","title":"L'hôtel de luxe","premise":"A couple describe a luxurious hotel they stayed in for their anniversary.","cefr":"C1","lines":[{"speaker":"Lise","fr":"Alors, cet hôtel à Monaco ?","en":"So, that hotel in Monaco?","spans":[]},{"speaker":"Margaux","fr":"Incomparable ! La chambre était luxueuse, avec une vue sur la mer.","en":"Incomparable! The room was luxurious, with a view of the sea.","spans":[[32,40,"fr_luxueux_adj"]]},{"speaker":"Lise","fr":"Des gens célèbres ?","en":"Any famous people?","spans":[]},{"speaker":"Margaux","fr":"Oui, un illustre acteur italien prenait son petit déjeuner à côté de nous !","en":"Yes, an illustrious Italian actor was having breakfast next to us!","spans":[[8,16,"fr_illustre_adj"]]},{"speaker":"Lise","fr":"Et tu lui as parlé ?","en":"And did you talk to him?","spans":[]},{"speaker":"Margaux","fr":"Non, j'étais livide, je ne pouvais rien dire !","en":"No, I went white, I couldn't say a thing!","spans":[[13,19,"fr_livide_adj"]]},{"speaker":"Lise","fr":"Ha ha ! Il faut être plus audacieuse !","en":"Ha ha! You need to be bolder!","spans":[]},{"speaker":"Margaux","fr":"Il y avait un jardin avec des fleurs multicolores.","en":"There was a garden with multicolored flowers.","spans":[]},{"speaker":"Lise","fr":"Et Marc ?","en":"And Marc?","spans":[]},{"speaker":"Margaux","fr":"Il était content. On est inséparables depuis vingt ans !","en":"He was happy. We've been inseparable for twenty years!","spans":[]},{"speaker":"Lise","fr":"Et ta valise ? Tu emportes toujours trop de choses.","en":"And your suitcase? You always take too much.","spans":[]},{"speaker":"Margaux","fr":"Non, cette fois, une petite valise compacte !","en":"No, this time a small, compact case!","spans":[]}]}],"portraits/timbres":[{"id":"C_R_appearance_07","title":"Le marché de nuit","premise":"Two friends wander through a summer night market with street performers.","cefr":"C1","lines":[{"speaker":"Malik","fr":"Regarde ce musicien ambulant ! Il joue de la guitare en marchant.","en":"Look at that strolling musician! He plays the guitar as he walks.","spans":[]},{"speaker":"Océane","fr":"Il est barbu, avec des cheveux bouclés. Il a l'air irlandais.","en":"He's bearded, with curly hair. He looks Irish.","spans":[[51,60,"fr_irlandais_adj"]]},{"speaker":"Malik","fr":"Oui, il chante une chanson irlandaise !","en":"Yes, he's singing an Irish song!","spans":[[27,37,"fr_irlandais_adj"]]},{"speaker":"Océane","fr":"Et là, un stand de cuisine mexicaine.","en":"And there, a Mexican food stand.","spans":[[27,36,"fr_mexicain_adj"]]},{"speaker":"Malik","fr":"Miam, des tacos ! Mais ce stand de beignets a l'air malsain, tout est frit dans de la vieille huile.","en":"Yum, tacos! But that doughnut stand looks unhealthy, everything's fried in old oil.","spans":[]},{"speaker":"Océane","fr":"Regarde cette vieille dame, elle est si frêle. Elle vend des bijoux.","en":"Look at that old lady, she's so frail. She's selling jewelry.","spans":[]},{"speaker":"Malik","fr":"Elle a de beaux bracelets. On en achète un ?","en":"She's got nice bracelets. Should we buy one?","spans":[]},{"speaker":"Océane","fr":"Oui ! Et regarde ce panneau oblique, il va tomber !","en":"Yes! And look at that sign leaning over, it's going to fall!","spans":[]},{"speaker":"Malik","fr":"Je le redresse.","en":"I'll straighten it.","spans":[]},{"speaker":"Océane","fr":"Merci, monsieur le héros !","en":"Thank you, Mr. Hero!","spans":[]}]}]};
